// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    PENNY_BY_PENNY c;
    function setUp() public { c = new PENNY_BY_PENNY(); }
    function testFuzz_property(address actor, uint256 amount, uint256 lockTime) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 0, 1e30);
        lockTime = bound(lockTime, 0, 1e30);
        SpyLog spy = new SpyLog();
        // drive c through SetLogFile before initialization
        c.SetLogFile(address(spy));
        // a Put must route its AddMessage through the stored log
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: amount}(abi.encodeWithSelector(c.Put.selector, lockTime));
        assertTrue(ok && spy.lastVal() == amount && spy.lastSender() == actor,
            "Put must record (sender, amount) in the configured log");
    }
}

contract SpyLog {
    address public lastSender;
    uint public lastVal;
    function AddMessage(address _adr, uint _val, string calldata) external {
        lastSender = _adr;
        lastVal = _val;
    }
}
